from sqlalchemy import Column, String, Uuid, ForeignKey, DateTime, Integer, Text, Index
from sqlalchemy.dialects.postgresql import JSONB
from datetime import datetime
from .base import Base


class EmailDraft(Base):
    """Email draft generated by AI for human review.
    
    Created by draft generation pipeline and added to HITL queue.
    Stores both the generated draft and metadata about its generation.
    """
    __tablename__ = "email_drafts"

    id = Column(Uuid, primary_key=True)
    tenant_id = Column(Uuid, ForeignKey("tenants.id"), nullable=False)
    queue_id = Column(Uuid, ForeignKey("email_processing_queue.id"), nullable=False)
    bot_id = Column(Uuid, ForeignKey("bots.id"), nullable=False)
    integration_id = Column(Uuid, ForeignKey("email_integrations.id"), nullable=False)

    # Original email references
    original_email_id = Column(String, nullable=False)  # Provider message ID
    thread_id = Column(String, nullable=True)
    sender_email = Column(String, nullable=True)
    original_subject = Column(String, nullable=True)

    # Draft content
    subject = Column(String, nullable=False)  # "Re: [Original Subject]"
    body = Column(Text, nullable=False)  # AI-generated response
    
    # Metadata
    citations = Column(JSONB, nullable=True)  # List of citation objects with source chunks
    confidence_score = Column(Integer, nullable=False)  # 0-100
    generation_time_ms = Column(Integer, nullable=True)  # Time taken to generate
    
    # Status tracking
    status = Column(String, nullable=False, default="pending_review")  # pending_review, approved, rejected, sent
    reviewed_by = Column(Uuid, ForeignKey("users.id"), nullable=True)
    reviewed_at = Column(DateTime, nullable=True)
    
    # Audit
    created_at = Column(DateTime, default=datetime.utcnow)
    updated_at = Column(DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    # Indexes for querying and RLS
    __table_args__ = (
        Index("ix_email_draft_tenant_status", "tenant_id", "status"),
        Index("ix_email_draft_bot_created", "bot_id", "created_at"),
        Index("ix_email_draft_queue_id", "queue_id"),
    )
